(()=>{
const en=document.documentElement.lang==='en',t=(zh,english)=>en?english:zh,$=id=>document.getElementById(id),data=window.GreenGoBusRoutes,card=$('busFavourites');if(!card||!data)return;
const section=document.createElement('section');section.className='saved-bus-map';section.innerHTML=`<div class="bus-map-heading"><h3>${t('线路站点地图','Bus stop map')}</h3><button type="button" id="fitBusMap" class="outline">${t('查看整条站序','Fit all stops')}</button></div><p>${t('圆点为保存的站点坐标；虚线按站序连接，仅为示意，不沿实际道路。点击站点可设为上车站或下车站。','Dots use saved stop coordinates. Dashed links show stop order, not the road route. Select a stop to set boarding or alighting.')}</p><div id="savedBusMap" role="region" aria-label="${t('常用公交站点交互地图','Interactive saved bus stop map')}"></div><p id="savedBusMapStatus" role="status">${t('正在载入底图…','Loading map…')}</p><p class="bus-map-legend">● ${t('黄色：上车站','Yellow: boarding')} · ● ${t('橙色：下车站','Orange: alighting')} · ${t('实线：所选区间示意','Solid line: selected stop interval')}</p><p>${t('站点与站序来自本地快照。底图由 OpenStreetMap 在线提供，拖动缩放可能请求地图瓦片，但不消耗 TransportAPI 额度。','Stops and sequences are local snapshots. OpenStreetMap supplies online base-map tiles; pan/zoom may request tiles but uses no TransportAPI quota.')}</p>`;
card.querySelector('details').before(section);const css=document.createElement('style');css.textContent='.saved-bus-map{margin:22px 0}.bus-map-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.saved-bus-map h3{margin:0}.saved-bus-map p{font-size:11px;line-height:1.7;color:#687d6e}#savedBusMap{height:420px;width:100%;border:1px solid #ccd7c8;border-radius:12px;background:#e8eddc;z-index:0}.bus-map-legend{font-weight:700;color:#244b3e!important}.bus-stop-popup{font-size:12px;min-width:170px}.bus-stop-popup b{display:block}.bus-stop-popup button{display:block;margin-top:8px;width:100%;padding:7px;border:1px solid #9caf9c;border-radius:5px;background:#fffdf7;color:#173e3c;cursor:pointer}.bus-stop-popup button:focus-visible{outline:3px solid #ffcc4a}@media(max-width:600px){#savedBusMap{height:340px}.bus-map-heading h3{font-size:18px}}';document.head.append(css);
let map,layer,routeBounds,patternId='';const pattern=()=>data.lines.find(l=>l.line===$('savedBusLine').value)?.patterns.find(p=>p.id===$('savedBusDirection').value);
function draw(){if(!map)return;const p=pattern();if(!p)return;layer.clearLayers();const board=p.stops.findIndex(s=>s.id===$('savedBusBoard').value),alight=p.stops.findIndex(s=>s.id===$('savedBusAlight').value),color={X20:'#b66346',X21:'#217359',X22:'#4279a2'}[$('savedBusLine').value];const coords=p.stops.map(s=>[s.lat,s.lon]);L.polyline(coords,{color,weight:3,dashArray:'5 8',opacity:.5,interactive:false}).addTo(layer);if(alight>board)L.polyline(coords.slice(board,alight+1),{color,weight:5,opacity:.85,interactive:false}).addTo(layer);
p.stops.forEach((s,i)=>{const selected=i===board||i===alight;const marker=L.circleMarker([s.lat,s.lon],{radius:selected?9:5,color:'#173e3c',weight:selected?2:1,fillColor:i===board?'#ffce45':i===alight?'#f39569':'#ffffff',fillOpacity:1}).addTo(layer);const label=document.createElement('span');label.textContent=s.name;marker.bindTooltip(label,{direction:'top',permanent:selected});const popup=document.createElement('div');popup.className='bus-stop-popup';const name=document.createElement('b');name.textContent=s.name;const id=document.createElement('p');id.textContent=s.id+(s.allJourneys?'':t(' · 部分班次',' · some trips'));popup.append(name,id);for(const [control,text]of [['savedBusBoard',t('设为上车站','Board here')],['savedBusAlight',t('设为下车站','Alight here')]]){const b=document.createElement('button');b.type='button';b.textContent=text;b.onclick=()=>{$(control).value=s.id;$(control).dispatchEvent(new Event('change'));map.closePopup();};popup.append(b);}marker.bindPopup(popup);});routeBounds=L.latLngBounds(coords);if(patternId!==p.id){patternId=p.id;map.fitBounds(routeBounds,{padding:[30,30],maxZoom:15});}$('savedBusMapStatus').textContent=$('savedBusLine').value+' · '+p.stops.length+' '+t('个保存站点；虚线不是道路导航路径。','saved stops; dashed links are not road navigation.');}
function init(){if(map||!window.L||!$('savedBusMap').offsetWidth||!$('savedBusMap').offsetHeight)return;map=L.map('savedBusMap',{scrollWheelZoom:false}).setView([52.45,-1.93],12);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).on('tileerror',()=>{$('savedBusMapStatus').textContent=t('底图暂不可用，站点和连线仍为本地数据；可继续使用列表。','Base map unavailable; stops and links remain local. The list is still available.');}).addTo(map);layer=L.layerGroup().addTo(map);draw();new ResizeObserver(()=>{map.invalidateSize();if(routeBounds)map.fitBounds(routeBounds,{padding:[30,30],maxZoom:15});}).observe($('savedBusMap'));}
for(const id of ['savedBusLine','savedBusDirection','savedBusBoard','savedBusAlight'])$(id).addEventListener('change',draw);$('fitBusMap').onclick=()=>{if(map&&routeBounds){map.invalidateSize();map.fitBounds(routeBounds,{padding:[30,30],maxZoom:15});}};
new ResizeObserver(init).observe($('savedBusMap'));if(window.L)init();else{const script=document.querySelector('script[src*="leaflet"]');if(script){script.addEventListener('load',init);script.addEventListener('error',()=>{$('savedBusMapStatus').textContent=t('地图组件未加载，保存的站点列表仍可使用。','Map component unavailable; saved stop lists remain usable.');});}else $('savedBusMapStatus').textContent=t('地图组件未加载，请使用保存站序。','Map component unavailable; use the saved stop list.');}
})();
